/*
Theme Name: Runner3 Editorial
Theme URI: https://github.com/louisalviss/runner-3
Author: Runner3
Description: A lightweight editorial WordPress theme inspired by contemporary magazine and studio layouts.
Version: 2.0.1
Requires at least: 6.6
Requires PHP: 8.1
Text Domain: runner3-starter
*/

:root {
  --ink: #11110f;
  --paper: #f2efe7;
  --paper-2: #e7e1d5;
  --signal: #dfff00;
  --muted: #807c73;
  --line: rgba(17,17,15,.22);
  --max: 1440px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: Arial, Helvetica, sans-serif;
  font-size: 16px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}
body::selection { background: var(--signal); color: var(--ink); }
a { color: inherit; }
img { display: block; width: 100%; height: auto; }
.wrap { width: min(calc(100% - 48px), var(--max)); margin-inline: auto; }
.kicker { font-size: 11px; text-transform: uppercase; letter-spacing: .16em; font-weight: 700; }
.serif { font-family: Georgia, 'Times New Roman', serif; font-weight: 400; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(242,239,231,.92);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--line);
}
.header-row { min-height: 72px; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 24px; }
.header-row > * { min-width: 0; }
.brand { font-weight: 900; letter-spacing: -.06em; text-decoration: none; font-size: 26px; text-transform: uppercase; }
.brand-dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; background: var(--signal); margin-left: 4px; vertical-align: top; }
.nav ul { display: flex; list-style: none; padding: 0; margin: 0; gap: 22px; }
.nav a { text-decoration: none; font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
.header-meta { justify-self: end; font-size: 11px; text-transform: uppercase; letter-spacing: .12em; }

.edition-hero { padding: 22px 0 34px; border-bottom: 1px solid var(--line); }
.hero-meta { display: flex; justify-content: space-between; gap: 20px; margin-bottom: 34px; }
.hero-title { margin: 0; font-size: clamp(74px, 13.8vw, 220px); line-height: .72; letter-spacing: -.085em; text-transform: uppercase; font-weight: 900; }
.hero-title em { display: block; margin-left: 18%; font-family: Georgia, 'Times New Roman', serif; font-weight: 400; text-transform: none; letter-spacing: -.07em; }
.hero-feature { margin-top: 42px; display: grid; grid-template-columns: 1.1fr .9fr; border-top: 1px solid var(--line); padding-top: 18px; gap: 18px; }
.hero-feature > * { min-width: 0; }
.hero-copy { display: grid; grid-template-rows: auto 1fr auto; min-height: 520px; padding-right: 8vw; }
.hero-feature h2 { font-size: clamp(40px, 5.7vw, 86px); letter-spacing: -.06em; line-height: .92; margin: 18px 0; font-weight: 700; overflow-wrap: break-word; }
.hero-feature h2 a { text-decoration: none; }
.hero-feature h2 a:hover { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 6px; }
.hero-excerpt { max-width: 520px; font-family: Georgia, 'Times New Roman', serif; font-size: clamp(18px, 1.65vw, 24px); line-height: 1.35; }
.hero-image { min-height: 520px; overflow: hidden; background: #ccc; }
.hero-image img { height: 100%; object-fit: cover; filter: grayscale(1) contrast(1.05); transition: transform .6s ease, filter .6s ease; }
.hero-image:hover img { transform: scale(1.025); filter: grayscale(.25); }

.section { padding: 64px 0; border-bottom: 1px solid var(--line); }
.section-head { display: grid; grid-template-columns: 1fr 2fr; gap: 24px; align-items: baseline; margin-bottom: 36px; }
.section-head > * { min-width: 0; }
.section-head h2 { margin: 0; font-size: clamp(38px, 5vw, 76px); letter-spacing: -.055em; line-height: .95; }
.story-grid { display: grid; grid-template-columns: repeat(12, minmax(0,1fr)); gap: 30px 18px; align-items: start; }
.story-card { grid-column: span 4; min-width: 0; padding-top: 10px; border-top: 1px solid var(--line); }
.story-card:nth-child(1) { grid-column: span 6; }
.story-card:nth-child(2), .story-card:nth-child(3) { grid-column: span 3; }
.story-image { display: block; width: 100%; aspect-ratio: 4/3; overflow: hidden; background: var(--paper-2); margin-bottom: 15px; }
.story-image img { width: 100%; height: 100%; object-fit: cover; filter: grayscale(1); transition: .45s ease; }
.story-card:hover img { filter: grayscale(0); transform: scale(1.02); }
.story-meta { display: flex; justify-content: space-between; gap: 12px; color: #4d4a44; font-size: 10px; text-transform: uppercase; letter-spacing: .12em; }
.story-meta > * { min-width: 0; }
.story-card h3 { margin: 12px 0 8px; font-size: clamp(25px, 2.4vw, 38px); line-height: 1; letter-spacing: -.045em; overflow-wrap: break-word; }
.story-card h3 a { text-decoration: none; }
.story-card p { margin: 0; max-width: 48ch; font-family: Georgia, 'Times New Roman', serif; color: #4c4942; overflow-wrap: break-word; }

.manifesto { background: var(--ink); color: var(--paper); padding: 88px 0; }
.manifesto-grid { display: grid; grid-template-columns: 1fr 3fr; gap: 24px; }
.manifesto-grid > * { min-width: 0; }
.manifesto p { margin: 0; font-size: clamp(34px, 5.3vw, 80px); line-height: 1.02; letter-spacing: -.055em; }
.manifesto p em { color: var(--signal); font-family: Georgia, 'Times New Roman', serif; font-weight: 400; }

.category-strip { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); border-top: 1px solid var(--line); border-left: 1px solid var(--line); }
.category-link { min-width: 0; min-height: 190px; padding: 18px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); display: flex; flex-direction: column; justify-content: space-between; text-decoration: none; transition: background .25s ease; }
.category-link:hover { background: var(--signal); }
.category-link strong { font-size: clamp(28px, 3vw, 46px); letter-spacing: -.05em; overflow-wrap: break-word; }
.category-link span { font-size: 11px; text-transform: uppercase; letter-spacing: .12em; }

.newsletter { padding: 92px 0; }
.newsletter-box { display: grid; grid-template-columns: minmax(0,1.3fr) minmax(0,.7fr); border-top: 1px solid var(--line); padding-top: 18px; gap: 34px; }
.newsletter h2 { margin: 0; font-size: clamp(54px, 8vw, 118px); line-height: .82; letter-spacing: -.075em; text-transform: uppercase; }
.newsletter h2 em { display: block; font-family: Georgia, 'Times New Roman', serif; text-transform: none; font-weight: 400; }
.newsletter-copy { min-width: 0; align-self: end; }
.newsletter-copy p { font-family: Georgia, 'Times New Roman', serif; font-size: 20px; }
.fake-form { display: flex; border-bottom: 1px solid var(--ink); margin-top: 32px; }
.fake-form input { min-width: 0; width: 100%; border: 0; background: transparent; padding: 14px 0; font: inherit; outline: none; }
.fake-form button { flex: 0 0 auto; border: 0; background: transparent; font-weight: 800; cursor: pointer; }

.archive-hero, .content-shell { padding: 64px 0 90px; }
.archive-hero h1, .article-title, .page-title { margin: 8px 0 36px; font-size: clamp(58px, 10vw, 150px); line-height: .82; letter-spacing: -.07em; overflow-wrap: break-word; }
.archive-grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 32px 18px; }
.archive-grid > * { min-width: 0; }
.article-shell { width: min(calc(100% - 48px), 1180px); margin: 0 auto; padding: 48px 0 100px; }
.article-head { display: grid; grid-template-columns: minmax(0,1fr) minmax(0,3fr); gap: 24px; border-bottom: 1px solid var(--line); padding-bottom: 34px; }
.article-title { margin-top: 0; }
.article-hero { margin: 28px 0 60px; aspect-ratio: 16/8.5; overflow: hidden; }
.article-hero img { height: 100%; object-fit: cover; filter: grayscale(.8); }
.article-body { width: min(760px, 75%); margin-left: 25%; font-family: Georgia, 'Times New Roman', serif; font-size: clamp(19px, 1.7vw, 23px); line-height: 1.62; }
.article-body h2, .article-body h3 { font-family: Arial, Helvetica, sans-serif; letter-spacing: -.04em; line-height: 1; margin-top: 2.2em; }
.article-body blockquote { margin: 2em 0; padding-left: 22px; border-left: 5px solid var(--signal); font-size: 1.35em; line-height: 1.25; }
.article-body a { text-decoration-thickness: 1px; text-underline-offset: 4px; }

.site-footer { background: var(--ink); color: var(--paper); padding: 48px 0 28px; }
.footer-top { display: grid; grid-template-columns: minmax(0,2fr) minmax(0,1fr) minmax(0,1fr); gap: 24px; margin-bottom: 80px; }
.footer-top > * { min-width: 0; }
.footer-mark { font-size: clamp(70px, 12vw, 180px); font-weight: 900; line-height: .75; letter-spacing: -.08em; }
.footer-col { font-size: 13px; }
.footer-col a { display: block; text-decoration: none; margin-bottom: 7px; }
.footer-bottom { border-top: 1px solid rgba(242,239,231,.3); padding-top: 18px; display: flex; justify-content: space-between; font-size: 10px; text-transform: uppercase; letter-spacing: .12em; }

@media (max-width: 900px) {
  .header-row { grid-template-columns: 1fr auto; }
  .nav { display: none; }
  .hero-feature, .newsletter-box, .manifesto-grid, .article-head { grid-template-columns: 1fr; }
  .hero-copy { min-height: 0; padding-right: 0; }
  .hero-image { min-height: auto; aspect-ratio: 4/3; }
  .story-card, .story-card:nth-child(n) { grid-column: span 6; }
  .category-strip { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .archive-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .article-body { width: min(760px,100%); margin-left: 0; }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .footer-mark { grid-column: 1 / -1; }
}

@media (max-width: 620px) {
  .wrap, .article-shell { width: min(calc(100% - 28px), var(--max)); }
  .site-header { position: relative; }
  .header-row { min-height: 62px; }
  .header-meta { display: none; }
  .edition-hero { padding-top: 16px; }
  .hero-meta { margin-bottom: 30px; }
  .hero-title { font-size: 24vw; line-height: .75; }
  .hero-title em { margin-left: 4%; }
  .hero-feature { margin-top: 26px; }
  .hero-feature h2 { font-size: 13vw; }
  .section { padding: 48px 0; }
  .section-head { grid-template-columns: 1fr; }
  .story-grid { gap: 34px 12px; }
  .story-card, .story-card:nth-child(n) { grid-column: 1 / -1; }
  .category-strip { grid-template-columns: 1fr; }
  .category-link { min-height: 120px; }
  .archive-grid { grid-template-columns: 1fr; }
  .manifesto { padding: 62px 0; }
  .newsletter { padding: 62px 0; }
  .footer-top { grid-template-columns: 1fr; margin-bottom: 50px; }
  .footer-mark { grid-column: auto; }
  .footer-bottom { gap: 14px; flex-direction: column; }
}

/* OFFSET / SIGNAL — front-page art direction */
.home {
  --night: #090a08;
  --night-2: #12130f;
  --acid: #dfff00;
  --cream: #f2efe7;
  --soft-line: rgba(242,239,231,.22);
}
.home main { overflow: clip; }
.home .site-header {
  position: fixed;
  inset: 0 0 auto;
  color: var(--cream);
  background: linear-gradient(to bottom, rgba(9,10,8,.86), rgba(9,10,8,.18) 72%, transparent);
  border-bottom-color: rgba(242,239,231,.16);
  backdrop-filter: blur(10px);
}
.home .brand-dot { box-shadow: 0 0 22px rgba(223,255,0,.55); }
.home .nav a, .home .brand, .home .header-meta { color: var(--cream); }
.home.admin-bar .site-header { top: 32px; }

.signal-stage {
  position: relative;
  min-height: 100svh;
  color: var(--cream);
  background:
    radial-gradient(circle at 78% 40%, rgba(223,255,0,.10), transparent 24%),
    radial-gradient(circle at 20% 88%, rgba(242,239,231,.07), transparent 30%),
    var(--night);
  isolation: isolate;
}
.signal-stage::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .24;
  background-image: linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.035) 1px, transparent 1px);
  background-size: 44px 44px;
  mask-image: linear-gradient(to bottom, black, transparent 86%);
}
.signal-stage__inner {
  position: relative;
  min-height: 100svh;
  padding-top: 116px;
  padding-bottom: 44px;
}
.signal-stage__meta {
  position: relative;
  z-index: 4;
  display: flex;
  justify-content: space-between;
  gap: 24px;
  color: rgba(242,239,231,.62);
}
.signal-title {
  position: relative;
  z-index: 3;
  width: min(1080px, 83%);
  margin: 7.5vh 0 0;
  font-size: clamp(78px, 11.6vw, 182px);
  line-height: .75;
  letter-spacing: -.082em;
  text-transform: uppercase;
  font-weight: 900;
}
.signal-title span { display: block; }
.signal-title span:nth-child(2) { margin-left: 8.5%; }
.signal-title .signal-title__serif {
  margin-left: 18%;
  color: var(--acid);
  font-family: Georgia, 'Times New Roman', serif;
  font-weight: 400;
  font-style: italic;
  text-transform: none;
  letter-spacing: -.07em;
}
.signal-orbit {
  position: absolute;
  z-index: 2;
  top: 18%;
  right: 1%;
  width: clamp(300px, 37vw, 580px);
  aspect-ratio: 1;
  color: inherit;
  text-decoration: none;
  transform: translate3d(calc(var(--mx,0) * 13px), calc(var(--my,0) * 10px + min(var(--scroll-y,0) * .018px, 24px)), 0);
  transition: transform .12s linear;
}
.signal-orbit__ring {
  position: absolute;
  inset: -5%;
  border: 1px solid rgba(223,255,0,.56);
  border-radius: 50%;
  animation: signal-spin 24s linear infinite;
}
.signal-orbit__ring::before,
.signal-orbit__ring::after {
  content: "";
  position: absolute;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: 0 0 18px rgba(223,255,0,.65);
}
.signal-orbit__ring::before { top: 13%; left: 13%; }
.signal-orbit__ring::after { right: 3%; bottom: 34%; }
.signal-orbit__image {
  position: absolute;
  inset: 9%;
  overflow: hidden;
  border-radius: 50%;
  background: #222;
  transform: translate3d(calc(var(--mx,0) * -8px), calc(var(--my,0) * -8px), 0);
}
.signal-orbit__image::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, transparent 35%, rgba(223,255,0,.14));
  mix-blend-mode: screen;
}
.signal-orbit__image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: grayscale(1) contrast(1.12) brightness(.78);
  transform: scale(1.05);
  transition: filter .5s ease, transform .8s cubic-bezier(.2,.7,.2,1);
}
.signal-orbit:hover .signal-orbit__image img { filter: grayscale(.15) contrast(1.04) brightness(.9); transform: scale(1.1); }
.signal-orbit__badge {
  position: absolute;
  right: 0;
  bottom: 9%;
  display: grid;
  place-items: center;
  width: 92px;
  height: 92px;
  border-radius: 50%;
  color: var(--night);
  background: var(--acid);
  transform: rotate(8deg);
}
.signal-orbit__badge b { font-size: 34px; line-height: .9; letter-spacing: -.06em; }
.signal-orbit__badge em { font-size: 9px; font-style: normal; font-weight: 800; letter-spacing: .16em; }
.signal-stage__feature {
  position: absolute;
  z-index: 4;
  right: 2%;
  bottom: 12%;
  width: min(360px, 30vw);
  padding-top: 12px;
  border-top: 1px solid rgba(242,239,231,.32);
}
.signal-stage__feature span { display: block; margin-bottom: 7px; color: rgba(242,239,231,.56); font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }
.signal-stage__feature strong { display: block; font-size: clamp(18px, 1.55vw, 24px); line-height: 1.05; letter-spacing: -.035em; }
.signal-stage__foot {
  position: absolute;
  z-index: 4;
  left: 0;
  right: 0;
  bottom: 42px;
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  align-items: end;
  gap: 24px;
}
.signal-stage__foot p { width: min(430px, 42vw); margin: 0; color: rgba(242,239,231,.62); font-family: Georgia, 'Times New Roman', serif; font-size: 15px; }
.signal-stage__foot a { color: var(--acid); text-decoration: none; font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }

.feature-scene { padding: clamp(86px, 10vw, 150px) 0; background: var(--cream); color: var(--ink); }
.feature-scene__grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0,1fr));
  grid-template-rows: auto auto;
  gap: 22px;
  align-items: start;
}
.scene-index {
  grid-column: 1 / 3;
  font-size: clamp(86px, 10vw, 154px);
  font-weight: 900;
  line-height: .75;
  letter-spacing: -.075em;
  color: transparent;
  -webkit-text-stroke: 1px rgba(17,17,15,.42);
}
.scene-copy { grid-column: 3 / 8; min-width: 0; padding-top: 4px; }
.scene-copy h2 { margin: 20px 0; font-size: clamp(48px, 6.2vw, 94px); line-height: .88; letter-spacing: -.065em; }
.scene-copy h2 a { text-decoration: none; }
.scene-copy p { max-width: 48ch; margin: 0 0 30px; font-family: Georgia, 'Times New Roman', serif; font-size: clamp(18px, 1.55vw, 23px); line-height: 1.45; color: #4b4841; }
.scene-link, .reel-link { display: inline-block; color: inherit; text-decoration: none; border-bottom: 1px solid currentColor; padding-bottom: 4px; font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.scene-image {
  grid-column: 8 / -1;
  min-width: 0;
  height: clamp(470px, 56vw, 760px);
  overflow: hidden;
  clip-path: polygon(9% 0,100% 0,100% 93%,0 100%,0 9%);
  background: #d3cdc0;
}
.scene-image img { width: 100%; height: 100%; object-fit: cover; filter: grayscale(.92) contrast(1.06); transition: transform .8s ease, filter .5s ease; }
.scene-image:hover img { transform: scale(1.025); filter: grayscale(.3); }
.scene-caption { grid-column: 8 / -1; color: #6b675f; }

.reel { padding: clamp(84px, 9vw, 140px) 0 0; color: var(--cream); background: var(--night-2); }
.reel-head { display: grid; grid-template-columns: 1fr 3fr; gap: 24px; align-items: start; margin-bottom: clamp(70px, 10vw, 150px); }
.reel-head h2 { margin: 0; font-size: clamp(68px, 9vw, 138px); line-height: .8; letter-spacing: -.075em; }
.reel-head h2 em { color: var(--acid); font-family: Georgia, 'Times New Roman', serif; font-weight: 400; }
.reel-list { border-top: 1px solid var(--soft-line); }
.reel-story {
  position: relative;
  display: grid;
  grid-template-columns: repeat(12, minmax(0,1fr));
  gap: 18px;
  align-items: center;
  min-height: min(78svh, 820px);
  padding: clamp(46px, 7vw, 100px) 0;
  border-bottom: 1px solid var(--soft-line);
}
.reel-number {
  position: absolute;
  top: 7%;
  right: 0;
  color: transparent;
  -webkit-text-stroke: 1px rgba(242,239,231,.18);
  font-size: clamp(110px, 18vw, 260px);
  font-weight: 900;
  line-height: .7;
  letter-spacing: -.09em;
  pointer-events: none;
}
.reel-image { grid-column: 1 / 7; display: block; min-width: 0; height: clamp(360px, 48vw, 650px); overflow: hidden; background: #24241f; }
.reel-image img { width: 100%; height: 100%; object-fit: cover; filter: grayscale(1) brightness(.73) contrast(1.12); transition: transform .8s ease, filter .5s ease; }
.reel-story:hover .reel-image img { transform: scale(1.025); filter: grayscale(.25) brightness(.86); }
.reel-copy { grid-column: 8 / -1; min-width: 0; position: relative; z-index: 2; }
.reel-meta { display: flex; justify-content: space-between; gap: 16px; color: rgba(242,239,231,.55); }
.reel-copy h3 { margin: 22px 0 20px; font-size: clamp(44px, 5.2vw, 78px); line-height: .91; letter-spacing: -.062em; overflow-wrap: break-word; }
.reel-copy h3 a { text-decoration: none; }
.reel-copy p { max-width: 42ch; margin: 0 0 34px; color: rgba(242,239,231,.66); font-family: Georgia, 'Times New Roman', serif; font-size: clamp(17px, 1.35vw, 21px); line-height: 1.48; }
.reel-story--reverse .reel-image { grid-column: 7 / -1; }
.reel-story--reverse .reel-copy { grid-column: 1 / 6; grid-row: 1; }
.reel-story--reverse .reel-number { right: auto; left: 0; }

.interrupt { padding: clamp(86px, 10vw, 160px) 0; color: var(--night); background: var(--acid); }
.interrupt-inner { display: grid; grid-template-columns: 1fr 4fr; gap: 24px; }
.interrupt p { margin: 0; font-size: clamp(48px, 7.8vw, 120px); line-height: .9; letter-spacing: -.07em; font-weight: 800; }
.interrupt p span { text-decoration: line-through; text-decoration-thickness: .06em; }
.interrupt p em { font-family: Georgia, 'Times New Roman', serif; font-weight: 400; }

.territories { padding: clamp(90px, 9vw, 140px) 0 0; color: var(--ink); background: var(--cream); }
.territories-head { display: grid; grid-template-columns: 1fr 3fr; gap: 24px; margin-bottom: 80px; }
.territories-head h2 { margin: 0; font-size: clamp(64px, 9vw, 140px); line-height: .82; letter-spacing: -.075em; }
.territory-list { border-top: 1px solid var(--ink); }
.territory {
  display: grid;
  grid-template-columns: minmax(80px,.7fr) minmax(0,4fr) minmax(120px,1fr);
  align-items: center;
  gap: 24px;
  min-height: clamp(130px, 14vw, 210px);
  padding: 20px max(24px, calc((100vw - min(1440px, calc(100vw - 48px))) / 2));
  border-bottom: 1px solid var(--ink);
  color: inherit;
  text-decoration: none;
  transition: background .3s ease, color .3s ease;
}
.territory:hover { color: var(--cream); background: var(--ink); }
.territory-num { font-size: 11px; font-weight: 800; letter-spacing: .16em; }
.territory strong { min-width: 0; font-size: clamp(48px, 7vw, 110px); line-height: .8; letter-spacing: -.07em; overflow-wrap: break-word; }
.territory > span:last-child { justify-self: end; font-size: 11px; letter-spacing: .12em; text-transform: uppercase; }

.signal-close { padding: clamp(100px, 12vw, 180px) 0; color: var(--cream); background: var(--night); }
.signal-close__grid { display: grid; grid-template-columns: 1fr 2.2fr 1fr; gap: 28px; align-items: end; }
.signal-close h2 { margin: 0; font-size: clamp(82px, 11vw, 168px); line-height: .72; letter-spacing: -.085em; text-transform: uppercase; }
.signal-close h2 em { color: var(--acid); font-family: Georgia, 'Times New Roman', serif; font-weight: 400; text-transform: none; }
.signal-close__copy p { margin: 0; color: rgba(242,239,231,.65); font-family: Georgia, 'Times New Roman', serif; font-size: 17px; }
.signal-form { display: flex; margin-top: 34px; border-bottom: 1px solid rgba(242,239,231,.7); }
.signal-form input { min-width: 0; width: 100%; padding: 14px 0; border: 0; outline: 0; color: var(--cream); background: transparent; font: inherit; }
.signal-form input::placeholder { color: rgba(242,239,231,.4); }
.signal-form button { flex: 0 0 auto; border: 0; color: var(--acid); background: transparent; font-weight: 900; cursor: pointer; }

[data-reveal] { opacity: 0; transform: translateY(28px); transition: opacity .75s ease, transform .85s cubic-bezier(.2,.7,.2,1); }
[data-reveal].is-visible { opacity: 1; transform: none; }
@keyframes signal-spin { to { transform: rotate(360deg); } }

@media (max-width: 900px) {
  .signal-stage__inner { padding-top: 104px; }
  .signal-title { width: 100%; margin-top: 8vh; font-size: clamp(72px, 15vw, 128px); }
  .signal-title span:nth-child(2) { margin-left: 0; }
  .signal-title .signal-title__serif { margin-left: 8%; }
  .signal-orbit { top: 39%; right: 7%; width: min(54vw, 440px); }
  .signal-stage__feature { right: auto; left: 0; bottom: 17%; width: min(340px, 48vw); }
  .signal-stage__foot { bottom: 30px; }
  .feature-scene__grid { grid-template-columns: repeat(8,minmax(0,1fr)); }
  .scene-index { grid-column: 1 / 3; }
  .scene-copy { grid-column: 3 / -1; }
  .scene-image { grid-column: 2 / -1; height: 62vw; margin-top: 30px; }
  .scene-caption { grid-column: 2 / -1; }
  .reel-head, .territories-head { grid-template-columns: 1fr 2fr; }
  .reel-story { min-height: 0; }
  .reel-image, .reel-story--reverse .reel-image { grid-column: 1 / 7; }
  .reel-copy, .reel-story--reverse .reel-copy { grid-column: 7 / -1; grid-row: auto; }
  .interrupt-inner { grid-template-columns: 1fr; }
  .signal-close__grid { grid-template-columns: 1fr 2fr; }
  .signal-close__grid > .kicker { grid-column: 1 / -1; }
}

@media (max-width: 620px) {
  .home.admin-bar .site-header { top: 46px; }
  .home .site-header { position: absolute; }
  .home .header-row { grid-template-columns: 1fr auto; }
  .signal-stage { min-height: 900px; }
  .signal-stage__inner { min-height: 900px; padding-top: 90px; padding-bottom: 28px; }
  .signal-stage__meta { font-size: 9px; }
  .signal-stage__meta span:last-child { display: none; }
  .signal-title { margin-top: 28px; font-size: clamp(66px, 22vw, 92px); line-height: .77; }
  .signal-title .signal-title__serif { margin-left: 0; }
  .signal-orbit { top: 38%; right: 2%; width: 78vw; max-width: 340px; }
  .signal-orbit__badge { width: 72px; height: 72px; }
  .signal-orbit__badge b { font-size: 27px; }
  .signal-stage__feature { left: 0; bottom: 120px; width: 62%; }
  .signal-stage__feature strong { font-size: 17px; }
  .signal-stage__foot { bottom: 24px; grid-template-columns: 1fr auto; }
  .signal-stage__foot p { width: 64%; font-size: 12px; line-height: 1.35; }
  .signal-stage__foot a { max-width: 92px; text-align: right; font-size: 9px; }
  .feature-scene { padding: 70px 0; }
  .feature-scene__grid { display: block; }
  .scene-index { margin-bottom: 40px; font-size: 92px; }
  .scene-copy h2 { font-size: 14.5vw; }
  .scene-copy p { font-size: 18px; }
  .scene-image { height: 112vw; margin-top: 50px; }
  .scene-caption { margin-top: 12px; }
  .reel { padding-top: 72px; }
  .reel-head { display: block; margin-bottom: 72px; }
  .reel-head h2 { margin-top: 30px; font-size: 17vw; }
  .reel-story, .reel-story--reverse { display: flex; flex-direction: column; align-items: stretch; gap: 22px; padding: 58px 0; }
  .reel-image, .reel-story--reverse .reel-image { order: 1; width: 100%; height: 108vw; }
  .reel-copy, .reel-story--reverse .reel-copy { order: 2; width: 100%; }
  .reel-number { top: 38px; right: 0 !important; left: auto !important; font-size: 36vw; }
  .reel-copy h3 { font-size: 13.2vw; }
  .reel-copy p { font-size: 17px; }
  .interrupt { padding: 76px 0; }
  .interrupt p { margin-top: 34px; font-size: 15vw; }
  .territories { padding-top: 76px; }
  .territories-head { display: block; margin-bottom: 56px; }
  .territories-head h2 { margin-top: 28px; font-size: 19vw; }
  .territory { grid-template-columns: 42px minmax(0,1fr); gap: 12px; min-height: 130px; padding: 20px 14px; }
  .territory strong { font-size: 14vw; }
  .territory > span:last-child { display: none; }
  .signal-close { padding: 84px 0; }
  .signal-close__grid { display: block; }
  .signal-close h2 { margin: 36px 0 58px; font-size: 22vw; }
  .signal-close__copy p { font-size: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  .signal-orbit, .signal-orbit__image, [data-reveal] { transform: none !important; transition: none !important; }
  .signal-orbit__ring { animation: none; }
  [data-reveal] { opacity: 1; }
}
